<script setup>
import{reactive}from'vue';import{register}from'../api';import{ElMessage}from'element-plus';import{useRouter}from'vue-router'
const router=useRouter(),form=reactive({username:'',password:'',confirmPassword:'',email:'',displayName:''})
async function submit(){if(!form.displayName.trim()||!form.username.trim()||!form.email.trim())return ElMessage.warning('请完整填写注册信息');if(form.password.length<6)return ElMessage.warning('密码至少6位');if(form.password!==form.confirmPassword)return ElMessage.warning('两次密码输入不一致');try{const{data}=await register({username:form.username.trim(),password:form.password,email:form.email.trim(),displayName:form.displayName.trim()});localStorage.setItem('craft-user',JSON.stringify(data));localStorage.setItem('craft-token',data.token);ElMessage.success('注册成功，已自动登录');router.push('/')}catch(e){ElMessage.error(e.response?.data?.message||'注册失败')}}
</script>
<template><div class="login-page"><div class="login-card register-card"><div class="eyebrow">CUSTOMER REGISTER</div><h2>客户自由注册</h2><p class="subtle">普通客户可以自行创建账号。管理员和商户账号由系统固定维护，不能通过注册页面获得管理权限。</p><el-form label-position="top"><el-form-item label="昵称"><el-input v-model="form.displayName" placeholder="例如：小周"/></el-form-item><el-form-item label="用户名"><el-input v-model="form.username" placeholder="用于登录，3-40位"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email" placeholder="用于账号识别"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" show-password placeholder="至少6位"/></el-form-item><el-form-item label="确认密码"><el-input v-model="form.confirmPassword" type="password" show-password/></el-form-item></el-form><button class="primary-btn" style="width:100%" @click="submit">注册普通客户账号</button><p style="text-align:center;font-size:13px"><RouterLink to="/login">已有账号，返回登录</RouterLink></p></div></div></template>